import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import os from "node:os";
import path from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";

import {
  computeLockHash,
  extractProfileSections,
  stripTomlCommentsAndBlanks,
} from "./cache-keys.mjs";

const SCRIPT_PATH = fileURLToPath(
  new URL("./cache-keys.mjs", import.meta.url),
);

const SAMPLE_LOCK = `# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "demo"
version = "0.1.0"
`;

function withTempDir(fn) {
  const dir = mkdtempSync(path.join(os.tmpdir(), "stow-cache-keys-test-"));
  try {
    return fn(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function writeFiles(root, files) {
  for (const [rel, content] of Object.entries(files)) {
    const full = path.join(root, rel);
    mkdirSync(path.dirname(full), { recursive: true });
    writeFileSync(full, content, "utf8");
  }
}

function parseGithubOutputs(raw) {
  const outputs = {};
  const lines = raw.replace(/\r\n/g, "\n").split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === "") continue;
    const heredoc = line.indexOf("<<");
    const eq = line.indexOf("=");
    if (heredoc !== -1 && (eq === -1 || heredoc < eq)) {
      const name = line.slice(0, heredoc);
      const delimiter = line.slice(heredoc + 2);
      const body = [];
      i++;
      while (i < lines.length && lines[i] !== delimiter) {
        body.push(lines[i]);
        i++;
      }
      outputs[name] = body.join("\n");
    } else if (eq !== -1) {
      outputs[line.slice(0, eq)] = line.slice(eq + 1);
    }
  }
  return outputs;
}

function runScript(cwd, extraEnv = {}) {
  const outDir = mkdtempSync(path.join(os.tmpdir(), "stow-cache-keys-out-"));
  const outputPath = path.join(outDir, "github-output.txt");
  writeFileSync(outputPath, "", "utf8");
  try {
    execFileSync(process.execPath, [SCRIPT_PATH], {
      cwd,
      env: {
        ...process.env,
        GITHUB_OUTPUT: outputPath,
        RUNNER_OS: "Linux",
        RUNNER_ARCH: "X64",
        GITHUB_JOB: "check",
        STOW_SHARED_KEY: "ci-check",
        STOW_EXTRA_KEY: "",
        STOW_WORKSPACES: ".",
        ...extraEnv,
      },
      stdio: ["ignore", "pipe", "pipe"],
    });
    return parseGithubOutputs(readFileSync(outputPath, "utf8"));
  } finally {
    rmSync(outDir, { recursive: true, force: true });
  }
}

describe("extractProfileSections", () => {
  it("keeps only [profile.*] tables and root profile.* keys while stripping comments and blanks", () => {
    const toml = `
# leading comment
profile.bench.debug = false # root dotted profile key

[package]
name = "demo"
version = "0.1.0"
description = """
Not a real header:
[profile.dev]
opt-level = 3
"""

[dependencies]
serde = "1"

[profile.dev] # dev profile
# comment inside profile
opt-level = 1 # speed up dev

[profile.dev.package."*"]
opt-level = 2

[profile.dev.package.'foo-bar']
opt-level = 3

[profile-extra]
not-a-profile = true

[package.metadata.profile]
ignored = true

[profile.ci-check]
inherits = "dev"
debug = 0

[[bin]]
name = "demo"
`;
    assert.equal(
      extractProfileSections(toml),
      [
        "profile.bench.debug = false",
        "[profile.dev]",
        "opt-level = 1",
        '[profile.dev.package."*"]',
        "opt-level = 2",
        "[profile.dev.package.'foo-bar']",
        "opt-level = 3",
        "[profile.ci-check]",
        'inherits = "dev"',
        "debug = 0",
      ].join("\n"),
    );
  });

  it("preserves # inside quoted strings and ignores multiline literal strings in non-profile tables", () => {
    const toml = `[package]
name = "demo"
description = '''
[profile.dev]
opt-level = 3
'''

[profile.dev.package."crate#1"]
opt-level = 2 # trailing comment
`;
    assert.equal(
      extractProfileSections(toml),
      ['[profile.dev.package."crate#1"]', "opt-level = 2"].join("\n"),
    );
  });
});

describe("stripTomlCommentsAndBlanks", () => {
  it("strips full-line and trailing comments while preserving # inside quoted strings", () => {
    const toml = `\uFEFF# header comment

[build]
rustflags = [
  "-C", "link-arg=#keep", # inline comment
]

[env]
PATH_SEP = "\\\\" # comment after escaped backslash
WIN = 'C:\\path\\to\\dir\\' # comment after literal string
`;
    assert.equal(
      stripTomlCommentsAndBlanks(toml),
      [
        "[build]",
        "rustflags = [",
        '"-C", "link-arg=#keep",',
        "]",
        "[env]",
        'PATH_SEP = "\\\\"',
        "WIN = 'C:\\path\\to\\dir\\'",
      ].join("\n"),
    );
  });
});

describe("computeLockHash", () => {
  it("returns identical 16-hex digest for identical Cargo.lock and [profile.*]", () => {
    withTempDir((dirA) => {
      withTempDir((dirB) => {
        const manifest = `[package]
name = "demo"
version = "0.1.0"

[profile.dev.package.foo]
opt-level = 2
`;
        writeFiles(dirA, { "Cargo.lock": SAMPLE_LOCK, "Cargo.toml": manifest });
        writeFiles(dirB, { "Cargo.lock": SAMPLE_LOCK, "Cargo.toml": manifest });

        const hashA = computeLockHash(".", dirA);
        const hashB = computeLockHash(".", dirB);
        assert.match(hashA, /^[0-9a-f]{16}$/);
        assert.equal(hashA, hashB);
      });
    });
  });

  it("rotates primary key when [profile.dev.package.foo] opt-level changes without Cargo.lock change", () => {
    withTempDir((dir) => {
      writeFiles(dir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"

[profile.dev.package.foo]
opt-level = 2
`,
      });
      const before = runScript(dir);

      writeFiles(dir, {
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"

[profile.dev.package.foo]
opt-level = 3
`,
      });
      const after = runScript(dir);

      assert.notEqual(before["local-key"], after["local-key"]);
      assert.notEqual(
        before["local-crates-io-key"],
        after["local-crates-io-key"],
      );
      // Restore-keys prefix stays identical so Actions warm-restores the old
      // cache and saves the updated cache under the new primary key.
      assert.equal(
        before["local-restore-keys"],
        after["local-restore-keys"],
      );
      assert.equal(
        before["local-crates-io-restore-keys"],
        after["local-crates-io-restore-keys"],
      );
      const scopedPrefix = before["local-restore-keys"].split("\n")[0];
      assert.ok(before["local-key"].startsWith(scopedPrefix));
      assert.ok(after["local-key"].startsWith(scopedPrefix));
      assert.match(
        after["local-key"],
        /^stow-v1-local-Linux-X64-(?:[0-9a-f]{16}|no-rustc)-ci-check-[0-9a-f]{16}$/,
      );
    });
  });

  it("rotates primary key when a custom [profile.ci-check] is added or edited without Cargo.lock change", () => {
    withTempDir((dir) => {
      writeFiles(dir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"
`,
      });
      const base = computeLockHash(".", dir);

      writeFiles(dir, {
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"

[profile.ci-check]
inherits = "dev"
debug = 0
`,
      });
      const withCustom = computeLockHash(".", dir);

      writeFiles(dir, {
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"

[profile.ci-check]
inherits = "dev"
debug = 1
`,
      });
      const editedCustom = computeLockHash(".", dir);

      assert.notEqual(base, withCustom);
      assert.notEqual(withCustom, editedCustom);
      assert.notEqual(base, editedCustom);
    });
  });

  it("keeps primary key unchanged when only [package] version, [dependencies], or comments change", () => {
    withTempDir((dir) => {
      writeFiles(dir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"

[dependencies]
itoa = "1"

[profile.dev]
debug = 0
`,
      });
      const before = computeLockHash(".", dir);

      writeFiles(dir, {
        "Cargo.toml": `# Top comment
[package]
name = "demo"
version = "0.2.0" # bumped version
description = "updated description"

[dependencies]
itoa = "1.0.15"

[workspace]
members = ["crates/*"]

# Profile comment
[profile.dev] # inline comment

debug = 0 # same setting
`,
      });
      const after = computeLockHash(".", dir);

      assert.equal(before, after);
    });
  });

  it("rotates primary key when .cargo/config.toml or .cargo/config changes, ignoring comments and blank lines", () => {
    withTempDir((dir) => {
      writeFiles(dir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]
name = "demo"
version = "0.1.0"
`,
      });
      const withoutConfig = computeLockHash(".", dir);

      writeFiles(dir, {
        ".cargo/config.toml": `# only a comment

`,
      });
      const commentOnlyConfig = computeLockHash(".", dir);
      assert.equal(withoutConfig, commentOnlyConfig);

      writeFiles(dir, {
        ".cargo/config.toml": `[build]
rustflags = ["-C", "debuginfo=0"]
`,
      });
      const withConfig = computeLockHash(".", dir);
      assert.notEqual(withoutConfig, withConfig);

      writeFiles(dir, {
        ".cargo/config.toml": `# Added comment

[build] # inline comment
rustflags = ["-C", "debuginfo=0"]
`,
      });
      const withConfigComments = computeLockHash(".", dir);
      assert.equal(withConfig, withConfigComments);

      writeFiles(dir, {
        ".cargo/config.toml": `[build]
rustflags = ["-C", "debuginfo=1"]
`,
      });
      const withChangedConfig = computeLockHash(".", dir);
      assert.notEqual(withConfig, withChangedConfig);
    });

    // Legacy `.cargo/config` filename without `.toml` extension
    withTempDir((dir) => {
      writeFiles(dir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]\nname = "demo"\nversion = "0.1.0"\n`,
      });
      const before = computeLockHash(".", dir);

      writeFiles(dir, {
        ".cargo/config": `[profile.dev]\nopt-level = 1\n`,
      });
      const after = computeLockHash(".", dir);
      assert.notEqual(before, after);
    });
  });

  it("hashes .cargo/config.toml from both cwd and nested workspace roots", () => {
    withTempDir((dir) => {
      writeFiles(dir, {
        "crates/app/Cargo.lock": SAMPLE_LOCK,
        "crates/app/Cargo.toml": `[package]
name = "app"
version = "0.1.0"

[profile.dev]
opt-level = 1
`,
      });
      const base = computeLockHash("crates/app", dir);

      writeFiles(dir, {
        ".cargo/config.toml": `[build]\nrustflags = ["-D", "warnings"]\n`,
      });
      const withRootConfig = computeLockHash("crates/app", dir);
      assert.notEqual(base, withRootConfig);

      writeFiles(dir, {
        "crates/app/.cargo/config.toml": `[profile.dev]\ndebug = 0\n`,
      });
      const withWsConfig = computeLockHash("crates/app", dir);
      assert.notEqual(withRootConfig, withWsConfig);
    });
  });

  it("ignores cwd Cargo.toml profiles when workspaces points only to another directory", () => {
    withTempDir((parent) => {
      const cwdDir = path.join(parent, "repo");
      const extDir = path.join(parent, "ext-crate");
      writeFiles(cwdDir, {
        "Cargo.toml": `[package]\nname = "repo"\nversion = "0.1.0"\n\n[profile.dist]\nlto = "thin"\n`,
      });
      writeFiles(extDir, {
        "Cargo.lock": SAMPLE_LOCK,
        "Cargo.toml": `[package]\nname = "ext"\nversion = "0.1.0"\n`,
      });
      const before = computeLockHash("../ext-crate", cwdDir);

      writeFiles(cwdDir, {
        "Cargo.toml": `[package]\nname = "repo"\nversion = "0.1.0"\n\n[profile.dist]\nlto = "fat"\n`,
      });
      const after = computeLockHash("../ext-crate", cwdDir);
      assert.equal(before, after);
    });
  });

  it("works cleanly when Cargo.toml has no [profile.*] section, is absent, or Cargo.lock is absent", () => {
    withTempDir((dir) => {
      writeFiles(dir, { "Cargo.lock": SAMPLE_LOCK });
      const withoutManifest = computeLockHash(".", dir);
      assert.match(withoutManifest, /^[0-9a-f]{16}$/);

      writeFiles(dir, {
        "Cargo.toml": `[package]\nname = "demo"\nversion = "0.1.0"\n`,
      });
      const withoutProfiles = computeLockHash(".", dir);
      assert.equal(withoutManifest, withoutProfiles);
    });

    withTempDir((emptyDir) => {
      assert.equal(computeLockHash(".", emptyDir), "unlocked");

      writeFiles(emptyDir, {
        "Cargo.toml": `[package]\nname = "demo"\nversion = "0.1.0"\n`,
      });
      assert.equal(computeLockHash(".", emptyDir), "unlocked");

      writeFiles(emptyDir, {
        "Cargo.toml": `[package]\nname = "demo"\nversion = "0.1.0"\n\n[profile.dev]\nopt-level = 1\n`,
      });
      const unlockedWithProfile = computeLockHash(".", emptyDir);
      assert.match(unlockedWithProfile, /^[0-9a-f]{16}$/);
      assert.notEqual(unlockedWithProfile, "unlocked");
    });
  });

  it("normalizes CRLF line endings identically to LF", () => {
    withTempDir((dirLf) => {
      withTempDir((dirCrlf) => {
        const manifestLf =
          '[package]\nname = "demo"\n\n[profile.dev]\nopt-level = 2\n';
        const configLf = '[build]\nrustflags = ["-C", "debuginfo=0"]\n';
        writeFiles(dirLf, {
          "Cargo.lock": SAMPLE_LOCK,
          "Cargo.toml": manifestLf,
          ".cargo/config.toml": configLf,
        });
        writeFiles(dirCrlf, {
          "Cargo.lock": SAMPLE_LOCK.replace(/\n/g, "\r\n"),
          "Cargo.toml": manifestLf.replace(/\n/g, "\r\n"),
          ".cargo/config.toml": configLf.replace(/\n/g, "\r\n"),
        });
        assert.equal(computeLockHash(".", dirLf), computeLockHash(".", dirCrlf));
      });
    });
  });
});
